import { FHSNode, PartitionPlan } from '../types/fhs';
import { flattenTree } from './treeUtils';

export function generateBashScript(root: FHSNode): string {
  const allNodes = flattenTree(root);
  const lines: string[] = [
    '#!/usr/bin/env bash',
    '# =====================================================================',
    '# FHS Architecture Provisioning Script',
    '# Generated by FHS Architect Planner',
    '# Adheres to Filesystem Hierarchy Standard (FHS 3.0 / Ubuntu)',
    '# =====================================================================',
    '',
    'set -euo pipefail',
    '',
    'echo "[*] Initializing Filesystem Hierarchy Structure..."',
    '',
  ];

  // Directories creation
  lines.push('# 1. Create directory structures');
  for (const node of allNodes) {
    if (node.path === '/') continue;
    if (node.type === 'directory') {
      lines.push(`mkdir -p "${node.path}"`);
    }
  }

  lines.push('');
  lines.push('# 2. Set ownership and permissions');
  for (const node of allNodes) {
    if (node.path === '/') continue;
    lines.push(`chown ${node.owner} "${node.path}"`);
    lines.push(`chmod ${node.permissions} "${node.path}"`);
  }

  lines.push('');
  lines.push('# 3. Create placeholder configuration and standard files');
  for (const node of allNodes) {
    if (node.type === 'file') {
      lines.push(`if [ ! -f "${node.path}" ]; then`);
      lines.push(`  touch "${node.path}"`);
      lines.push(`  chown ${node.owner} "${node.path}"`);
      lines.push(`  chmod ${node.permissions} "${node.path}"`);
      lines.push(`fi`);
    }
  }

  lines.push('');
  lines.push('echo "[✓] FHS structure successfully provisioned."');
  return lines.join('\n');
}

export function generateFstab(partitions: PartitionPlan[]): string {
  const lines: string[] = [
    '# /etc/fstab: static file system information.',
    '# Generated by FHS Architect Planner',
    '#',
    '# <file system>                           <mount point>   <type>  <options>       <dump>  <pass>',
  ];

  for (const p of partitions) {
    const devPad = p.device.padEnd(40, ' ');
    const mountPad = p.mountPoint.padEnd(15, ' ');
    const typePad = p.fsType.padEnd(7, ' ');
    const optPad = (p.readOnly ? (p.options.includes('ro') ? p.options : `ro,${p.options}`) : p.options).padEnd(15, ' ');
    lines.push(`${devPad} ${mountPad} ${typePad} ${optPad} ${p.dump}       ${p.pass}`);
  }

  return lines.join('\n');
}

export function generateAsciiTree(node: FHSNode, prefix: string = '', isTail: boolean = true): string {
  const marker = isTail ? '└── ' : '├── ';
  const nameDisplay = node.path === '/' ? '/' : (node.name + (node.type === 'directory' ? '/' : ''));
  const metaDisplay = ` [${node.shareability[0].toUpperCase()}/${node.volatility[0].toUpperCase()}] (${node.permissions} ${node.owner})`;
  let result = prefix + (node.path === '/' ? '' : marker) + nameDisplay + metaDisplay + '\n';

  if (node.children && node.children.length > 0) {
    const nextPrefix = prefix + (node.path === '/' ? '' : (isTail ? '    ' : '│   '));
    for (let i = 0; i < node.children.length; i++) {
      const child = node.children[i];
      const isLast = i === node.children.length - 1;
      result += generateAsciiTree(child, nextPrefix, isLast);
    }
  }

  return result;
}

export function generateDockerfile(root: FHSNode): string {
  const allNodes = flattenTree(root);
  const customDirs = allNodes.filter(n => n.standardHierarchy === 'custom' && n.type === 'directory');

  const lines: string[] = [
    '# syntax=docker/dockerfile:1',
    'FROM ubuntu:24.04',
    '',
    'LABEL maintainer="FHS System Architect"',
    'LABEL org.opencontainers.image.description="Container compliant with Filesystem Hierarchy Standard"',
    '',
    '# Ensure minimal package installation and standard FHS dirs',
    'RUN apt-get update && apt-get install -y --no-install-recommends \\',
    '    ca-certificates \\',
    '    curl \\',
    '    && rm -rf /var/lib/apt/lists/*',
    '',
  ];

  if (customDirs.length > 0) {
    lines.push('# Custom Application and Data Hierarchies');
    lines.push(`RUN mkdir -p \\`);
    customDirs.forEach((dir, idx) => {
      const isEnd = idx === customDirs.length - 1;
      lines.push(`    ${dir.path}${isEnd ? '' : ' \\'}`);
    });
    lines.push('');
  }

  lines.push('WORKDIR /opt');
  lines.push('CMD ["/bin/bash"]');

  return lines.join('\n');
}
